import { useTranslation } from 'react-i18next';
import { useData } from 'vike-react/useData';
import { Text } from '../../components/ui/text';
import type { PageData } from './+data';
import { Metadata } from '~/components/layout/Metadata';
import { getAlbumArtPublicPath } from '~/utils/assets';
import { Stack, styled } from 'styled-system/jsx';
import { Table } from '~/components/ui/table';
import { Link } from '~/components/ui/link';

export function Page() {
  const { t } = useTranslation();

  const data: PageData = useData();
  const title = t('title');

  type DifficultyKey = keyof PageData['songs'][0]['difficulty'];

  const difficultyConfigs: {
    key: DifficultyKey;
    param: '1' | '2' | '3' | '4';
    label: string;
  }[] = [
    { key: 'normal', param: '1', label: t('song_table.normal') },
    { key: 'hard', param: '2', label: t('song_table.hard') },
    { key: 'expert', param: '3', label: t('song_table.expert') },
    { key: 'master', param: '4', label: t('song_table.master') }
  ];

  return (
    <>
      <Metadata title={title} />
      <Stack alignItems="center" w="full" _print={{ display: 'none' }}>
        <Text textAlign="center" fontSize="3xl" fontWeight="bold">
          {title}
        </Text>
        <Text textAlign="center">{t('description')}</Text>
        <Table.Root>
          <Table.Head>
            <Table.Row>
              <Table.Header hideBelow="md">{/* Album Art Column */}</Table.Header>
              <Table.Header>{t('song_table.name')}</Table.Header>
              <Table.Header hideBelow="md">{t('song_table.description')}</Table.Header>
              <Table.Header hideBelow="md" textAlign="center">
                {t('song_table.duration')}
              </Table.Header>
              {difficultyConfigs.map((config) => (
                <Table.Header key={config.key} minW="16" p={{ base: 1, md: 4 }} textAlign="center">
                  {config.label}
                </Table.Header>
              ))}
            </Table.Row>
          </Table.Head>
          <Table.Body>
            {data.songs.map((d) => {
              return (
                <Table.Row key={d.id}>
                  <Table.Cell hideBelow="md" width="16" px="0">
                    <Link href={`/${d.id}`}>
                      <styled.img
                        src={getAlbumArtPublicPath(d.id)}
                        alt={`${d.title} album art`}
                        objectFit="contain"
                      />
                    </Link>
                  </Table.Cell>
                  <Table.Cell>
                    <Link href={`/${d.id}`} fontWeight="bold">
                      {d.title}
                    </Link>
                  </Table.Cell>
                  <Table.Cell hideBelow="md">{d.description}</Table.Cell>
                  <Table.Cell hideBelow="md" textAlign="center">
                    {Math.floor(d.duration / 1000)}
                  </Table.Cell>
                  {difficultyConfigs.map((config) => (
                    <Table.Cell
                      key={config.key}
                      minW="16"
                      p={{ base: 0, md: 4 }}
                      textAlign="center"
                      bgColor={`difficulty.${config.key}.bg`}
                    >
                      <Link href={`/${d.id}?difficulty=${config.param}`}>
                        <Stack gap="0" alignItems="center" textAlign="center">
                          <Stack gap="0.5" direction="row" alignItems="baseline">
                            <Text color="fg.default" fontSize="xs">
                              Lv.
                            </Text>
                            <Text fontSize="xl" fontWeight="bold" lineHeight="1">
                              {d.difficulty[config.key]}
                            </Text>
                          </Stack>
                          <Text color="fg.default" fontSize="xs" lineHeight="1">
                            ({d.maxCombo[config.key]})
                          </Text>
                        </Stack>
                      </Link>
                    </Table.Cell>
                  ))}
                </Table.Row>
              );
            })}
          </Table.Body>
        </Table.Root>
      </Stack>
    </>
  );
}
